CREATE DATABASE IF NOT EXISTS `showroom-thomy` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `showroom-thomy`;
CREATE TABLE IF NOT EXISTS `mobil` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`nama_mobil` varchar(255) NOT NULL,`merk` varchar(255) NOT NULL,`tahun` year NOT NULL,`harga` bigint NOT NULL,`stok` int NOT NULL DEFAULT 1,`deskripsi` text NOT NULL,`gambar` varchar(255) NOT NULL,`status` varchar(255) NOT NULL DEFAULT 'ready',`transmisi` varchar(255) DEFAULT NULL,`bahan_bakar` varchar(255) DEFAULT NULL,`warna` varchar(255) DEFAULT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `mobil_images` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`mobil_id` bigint unsigned NOT NULL,`gambar` varchar(255) NOT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),CONSTRAINT `mobil_images_mobil_id_foreign` FOREIGN KEY (`mobil_id`) REFERENCES `mobil` (`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `transaksi` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`invoice` varchar(255) NOT NULL,`user_id` bigint unsigned NOT NULL,`total_harga` decimal(15,2) NOT NULL,`metode_pembayaran` enum('cash','kredit') NOT NULL,`dp` decimal(15,2) DEFAULT NULL,`tenor` int DEFAULT NULL,`cicilan_per_bulan` decimal(15,2) DEFAULT NULL,`sisa_pembayaran` decimal(15,2) DEFAULT NULL,`status` enum('pending','proses','selesai') NOT NULL DEFAULT 'pending',`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `detail_transaksi` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`transaksi_id` bigint unsigned NOT NULL,`mobil_id` bigint unsigned NOT NULL,`qty` int NOT NULL,`harga` decimal(15,2) NOT NULL,`subtotal` decimal(15,2) NOT NULL DEFAULT 0,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),FOREIGN KEY (`transaksi_id`) REFERENCES `transaksi` (`id`) ON DELETE CASCADE,FOREIGN KEY (`mobil_id`) REFERENCES `mobil` (`id`) ON DELETE CASCADE);
